export function getODMLAProfile(acNo: number): MLAProfile | undefined {
  return OD_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getODMLAsByParty(party: string): MLAProfile[] {
  return OD_MLA_PROFILES.filter(p => p.party === party);
}

export function getODFemaleMLAs(): MLAProfile[] {
  return OD_MLA_PROFILES.filter(p => p.gender === 'F');
}
